{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "`judge-jev check` MUST take one of two argument forms: a single record\nwith a location and a mode, or a `--profile`."
  },
  "record": {
    "id": "REQ-JEV-0201",
    "title": "One record per check",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "Definitions: A record is one requirement (REQ), non-functional requirement\n(NFR) or architecture decision record (ADR) as Raptor imports it; REQ, NFR\nand ADR are its record kinds. A location is the text judged against a\nrecord: a whole file (`path`), a Markdown section (`path#Heading`) or a code\nsymbol (`path::Symbol`) (REQ-JEV-0207). A mode (target mode) names what a\nlocation holds: `prompt` (prompt text), `skill` (a skill file), `task` (a\ntask template) or `code` (source code). A question set is the data file of\nquestions judge-jev sends to Jev about a location for one record kind and\ntarget class. `--profile` names a profile: a TOML file listing locations,\neach with its mode and the ids of the records that govern it (REQ-JEV-0204).",
      "statements": [
        {
          "modal": "Must",
          "text": "`judge-jev check` MUST take one of two argument forms: a single record\nwith a location and a mode, or a `--profile`."
        },
        {
          "modal": "Must",
          "text": "In the single-record form, `judge-jev check` MUST take one record id,\ngiven with exactly one record-kind flag: `--req` (requirement), `--adr`\n(architecture decision record) or `--nfr` (non-functional requirement)."
        },
        {
          "modal": "Must",
          "text": "In the single-record form, `judge-jev check` MUST take exactly one\n`--location`."
        },
        {
          "modal": "Must",
          "text": "In the single-record form, `judge-jev check` MUST take exactly one\n`--mode`."
        },
        {
          "modal": "Must",
          "text": "Each record kind MUST use its own question set."
        }
      ]
    },
    "rationale": "A requirement, a decision and a non-functional requirement are each\nviolated in a different way.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "The same location checked with `--req` and with `--adr` sends\ndifferent question sets.",
          "checked": false
        }
      ],
