{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "Each Jev request MUST carry exactly one record."
  },
  "record": {
    "id": "REQ-JEV-0202",
    "title": "One record and one location per request",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "Definitions: Jev is TypeSafe's hosted judge model: it answers each\nmultiple-choice question about a text with one choice and a confidence from\n0 to 1. A Jev request is one call to it. A record is one requirement (REQ),\nnon-functional requirement (NFR) or architecture decision record (ADR) as\nRaptor imports it; REQ, NFR and ADR are its record kinds. A location is the\ntext judged against a record: a whole file (`path`), a Markdown section\n(`path#Heading`) or a code symbol (`path::Symbol`) (REQ-JEV-0207). A pair is\none (record, location) pair. A stream of single requests is a sequence of\nJev requests, one per pair, sent one at a time through the batch command\n(REQ-JEV-0002).",
      "statements": [
        {
          "modal": "Must",
          "text": "Each Jev request MUST carry exactly one record."
        },
        {
          "modal": "Must",
          "text": "Each Jev request MUST carry exactly one location."
        },
        {
          "modal": "Must",
          "text": "A run over many pairs MUST send them as a stream of single requests."
        }
      ]
    },
    "rationale": "Jev judges one record and location at a time; packing records into one request hides\nwhich one failed. Batching is streaming single requests, which the batch\ncommand already does.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "A profile mapping one file to three records sends three requests.",
          "checked": false
        }
      ],
      "test_evidence": []
    },
