{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "judge-jev MUST ship one question set per combination of record kind and\ntarget class (agent text or code)."
  },
  "record": {
    "id": "REQ-JEV-0205",
    "title": "Question sets ship with the tool",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "Definitions: A record is one requirement (REQ), non-functional requirement\n(NFR) or architecture decision record (ADR) as Raptor imports it; REQ, NFR\nand ADR are its record kinds. A question set is the data file of questions\njudge-jev sends to Jev about a location for one record kind and target\nclass. A target class is agent text (modes `prompt`, `skill` and `task`) or\ncode (mode `code`). A quality decision tree is the data file of questions\nthat judges whether a record is well written: waves of questions, with rules\nthat turn Jev's answers into the next wave or a verdict (REQ-JEV-0101). A\nquestion-set id is the `id` field of a question set or tree file. The\ncontent digest of a file is the SHA-256 of its bytes. A log entry is one\nevent a run writes through the sc-observability logger (REQ-JEV-0008).",
      "statements": [
        {
          "modal": "Must",
          "text": "judge-jev MUST ship one question set per combination of record kind and\ntarget class (agent text or code)."
        },
        {
          "modal": "Must",
          "text": "judge-jev MUST ship one quality decision tree per record kind."
        },
        {
          "modal": "Must",
          "text": "Every shipped question and prompt text MUST be approved by Rand before\nit ships."
        },
        {
          "modal": "Must",
          "text": "Question sets MUST be data files shipped with the tool."
        },
        {
          "modal": "Must",
          "text": "Quality decision trees MUST be data files shipped with the tool."
