          "modal": "Must",
          "text": "`judge-jev check` MUST accept `--dry-run`."
        },
        {
          "modal": "Must",
          "text": "A dry run MUST compose every request without calling Jev."
        },
        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the record id."
