        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the question set as its shipped id or its\noverride path."
        },
        {
          "modal": "Must",
          "text": "In `task` mode, each dry-run entry MUST report the vars file."
        },
        {
          "modal": "Must",
          "text": "In `task` mode, each dry-run entry MUST report the rendered text."
        },
        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the full composed request."
