{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "For every input, every `judge-jev` command MUST print exactly one JSON\nobject."
  },
  "record": {
    "id": "REQ-JEV-0211",
    "title": "A typed result for every input",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "Definitions: Jev is TypeSafe's hosted judge model: it answers each\nmultiple-choice question about a text with one choice and a confidence from\n0 to 1. A Jev request is one call to it. A `judge-jev` command's result is\nthe JSON object it prints on success. A typed error is a JSON error object\nwith a stable `code` (such as `INPUT.MALFORMED`), a `message` and a\n`suggested_action`. A tree is a quality decision tree file, a question set a\nfile of questions, an index a Raptor import index, a request stream the\nrequest lines of the batch command, and a run directory the folder that\nholds a run's log. A log event is one event written through the\nsc-observability logger; the logger's event size limit is 65536 bytes\n(sc-observability 1.5.0).",
      "statements": [
        {
          "modal": "Must",
          "text": "For every input, every `judge-jev` command MUST print exactly one JSON\nobject."
        },
        {
          "modal": "Must",
          "text": "The JSON object a `judge-jev` command prints MUST be its result or a\ntyped error."
        },
        {
          "modal": "Must",
          "text": "`judge-jev` MUST refuse an invalid tree, question set, index, request\nstream or run directory before its first Jev request."
        },
        {
          "modal": "Must",
          "text": "`judge-jev` MUST check that every log event of a request (the request,\nJev's largest possible answer and the result) fits the logger's event\nsize limit before sending the request."
        }
      ]
    },
    "rationale": "Rand Lee, 2026-11-08: \"Crash is not acceptable for any input.\" A refusal\nafter a paid call wastes the call; a crash loses its answer.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "The sweep tests (every field of a tree, index and answers file\nreplaced by each of a fixed list of wrong values, deleted or given an\nextra key, and raw JSON no value expresses) produce no `SCRIPT.INTERNAL`\nand no refusal after a request is sent.",
          "checked": false
        },
        {
          "text": "Invalid UTF-8 on stdin is refused with `INPUT.MALFORMED`.",
          "checked": false
        }
      ],
      "test_evidence": []
