{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "judge-jev MUST send every Jev request through one batch command."
  },
  "record": {
    "id": "REQ-JEV-0002",
    "title": "One batch command calls Jev",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-07",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "Definitions: Jev is TypeSafe's hosted judge model: it answers each\nmultiple-choice question about a text with one choice and a confidence from\n0 to 1. A Jev request is one call to it. The batch command is `jev_judge.py\nbatch`: it reads request lines (one JSON request per line), sends each to\nJev and writes a result line. A result envelope is the JSON result line for\none request, holding its answers or its error\n(`assets/schemas/jev-batch-result.schema.json`). A typed error code is a\nstable dotted code naming a failure, such as `JEV.NETWORK` or\n`JEV.RATE_LIMITED`. The fixed retry policy is one retry of a call that\nfailed with a recoverable or transient error (`JEV.RATE_LIMITED`,\n`JEV.OVERLOADED`, `JEV.NETWORK`, `JEV.RESPONSE_INVALID`), after the\nresponse's Retry-After delay capped at 30 seconds, or after 1 second without\none. The request size limit is the `--max-request-bytes` value, at most\n64000 bytes; by default 24000 bytes with `--gate plan` and 64000 bytes with\n`--gate dev`. The sc-observability logger is the JSON-lines logger of the\nsc-observability package (version 1.5.0), which writes\n`.sc/judge-jev/logs/judge-jev.log.jsonl`.",
      "statements": [
        {
          "modal": "Must",
          "text": "judge-jev MUST send every Jev request through one batch command."
        },
        {
          "modal": "Must",
          "text": "The batch command MUST read request lines."
        },
        {
          "modal": "Must",
          "text": "The batch command MUST write one result envelope per request."
        },
        {
          "modal": "Must",
          "text": "The batch command MUST use typed error codes."
        },
        {
          "modal": "Must",
          "text": "The batch command MUST apply a fixed retry policy."
        },
        {
          "modal": "Must",
          "text": "The batch command MUST enforce request size limits."
        },
        {
          "modal": "Must",
          "text": "The batch command MUST log every request through the sc-observability\nlogger (REQ-JEV-0008)."
        },
        {
          "modal": "Must",
          "text": "The batch command MUST log every answer through the sc-observability\nlogger (REQ-JEV-0008)."
        }
      ]
    },
    "rationale": "One call path keeps the Jev core stable while a Rust implementation\nreplaces it (ADR-JEV-0001).",
    "success_criteria": {
