{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "judge-jev MUST obtain its record database by asking Raptor to build a\nlocal SQLite database from the repository's Raptor-parseable Markdown on\neach run."
  },
  "record": {
    "id": "REQ-JEV-0006",
    "title": "Local record database built through Raptor",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-07",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "Definitions: Raptor is the requirements tool that imports Markdown records\ninto its record store and serves them to other tools (ADR-JEV-0002).\nRaptor-parseable Markdown is Markdown in the record format Raptor's import\nreads. SQLite is a single-file SQL (Structured Query Language) database.\nDolt is a SQL database with Git-style branches; a SQLite snapshot of a Dolt\nbranch is a SQLite copy of that branch's records. The Raptor interface is\nthe way Raptor hands records to another tool.",
      "statements": [
        {
          "modal": "Must",
          "text": "judge-jev MUST obtain its record database by asking Raptor to build a\nlocal SQLite database from the repository's Raptor-parseable Markdown on\neach run."
        },
        {
          "modal": "Must",
          "text": "When Raptor supplies a SQLite snapshot of a Dolt branch, judge-jev MUST\nquery it through the same Raptor interface."
        }
      ]
    },
    "rationale": "Querying SQLite is the same work whether it was built from Markdown or\npulled from Dolt, so the source can change without changing judge-jev.",
    "success_criteria": {
      "text": "",
